WITH enriched AS (SELECT *, LEAD(revenue, 1) OVER (PARTITION BY product_id ORDER BY revenue ASC, id ASC) AS next_revenue, ROUND(revenue / SUM(revenue) OVER (PARTITION BY store_id), 4) AS revenue_share, MIN(revenue) OVER w_grp AS product_id_min_revenue, LAG(revenue, 1) OVER (ORDER BY sale_date ASC, id ASC) AS prev_revenue, AVG(revenue) OVER (ORDER BY revenue ASC, id ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS revenue_avg_6 FROM store_sales WINDOW w_grp AS (PARTITION BY product_id, store_id)) SELECT s.id, s.store_id, s.product_id, s.sale_date, s.units, s.next_revenue, s.revenue_share, s.prev_revenue, (SELECT SUM(x.unit_price) FROM order_items x WHERE x.product_id = s.product_id) AS sum_order_item_unit_price FROM enriched s ORDER BY revenue_share DESC;
